import React, { useCallback, useEffect, useMemo, useState } from 'react';
import { Card, Space, Table, Tag, Typography, Form, Select, DatePicker, Input, Button, Statistic, Row, Col, message } from 'antd';
import type { ColumnsType, TablePaginationConfig, SorterResult, FilterValue } from 'antd/es/table/interface';
import dayjs from 'dayjs';
import { apiRequest } from '../api';
import { useNavigate } from 'react-router-dom';

type Incident = {
  id: string | number;
  title?: string;
  status?: string;
  severity?: number | string;
  source?: string;
  trace_id?: string;
  detected_at?: string;
  updated_at?: string;
};

type IncidentsListResponse = {
  items: Incident[];
  total: number;
};

type MetricsResponse = {
  status_counters?: Record<string, number>;
  severity_counters?: Record<string, number>;
};

const severityTag = (sev?: number | string) => {
  const n = typeof sev === 'string' ? parseInt(sev, 10) : (sev ?? 0);
  const map: Record<number, { color: string; text: string }> = {
    1: { color: 'red', text: 'SEV1' },
    2: { color: 'volcano', text: 'SEV2' },
    3: { color: 'orange', text: 'SEV3' },
    4: { color: 'gold', text: 'SEV4' },
    5: { color: 'green', text: 'SEV5' },
  };
  const cfg = map[n] || { color: 'default', text: String(sev ?? '-') };
  return <Tag color={cfg.color}>{cfg.text}</Tag>;
};

const statusTag = (status?: string) => {
  const s = String(status || '').toLowerCase();
  const color = s === 'open' ? 'red' : s === 'in_progress' ? 'gold' : s === 'resolved' ? 'green' : s === 'closed' ? 'default' : 'blue';
  return <Tag color={color}>{status || '-'}</Tag>;
};

const { RangePicker } = DatePicker;

const DEFAULT_PAGE_SIZE = 20;

const IncidentsList: React.FC = () => {
  const nav = useNavigate();
  const [form] = Form.useForm();

  const [data, setData] = useState<Incident[]>([]);
  const [total, setTotal] = useState<number>(0);
  const [loading, setLoading] = useState<boolean>(false);
  const [page, setPage] = useState<number>(1);
  const [pageSize, setPageSize] = useState<number>(DEFAULT_PAGE_SIZE);
  const [sortBy, setSortBy] = useState<string>('detected_at');
  const [sortDir, setSortDir] = useState<'asc'|'desc'>('desc');

  const [metrics, setMetrics] = useState<MetricsResponse>({});
  const [metricsLoading, setMetricsLoading] = useState<boolean>(false);

  const fetchMetrics = useCallback(async () => {
    try {
      setMetricsLoading(true);
      const resp = await apiRequest('/api/admin/incidents/metrics', 'GET');
      setMetrics(resp || {});
    } catch (e: any) {
      // дружелюбно, но без спама
      console.warn('Не удалось загрузить метрики инцидентов', e?.message || e);
    } finally {
      setMetricsLoading(false);
    }
  }, []);

  const fetchData = useCallback(async () => {
    try {
      setLoading(true);
      const values = form.getFieldsValue();
      const params = new URLSearchParams();
      if (values.status) params.set('status', values.status);
      if (values.severity) params.set('severity', String(values.severity));
      if (values.source) params.set('source', values.source);
      if (values.severity_lte) params.set('severity_lte', String(values.severity_lte));
      if (values.trace_id) params.set('trace_id', values.trace_id.trim());
      if (Array.isArray(values.date_range) && values.date_range.length === 2) {
        const [from, to] = values.date_range as any[];
        if (from) params.set('date_from', dayjs(from).toISOString());
        if (to) params.set('date_to', dayjs(to).toISOString());
      }
      params.set('page', String(page));
      params.set('page_size', String(pageSize));
      params.set('sort_by', sortBy);
      params.set('sort_dir', sortDir);
      const resp: IncidentsListResponse = await apiRequest(`/api/admin/incidents?${params.toString()}`, 'GET');
      setData(resp?.items || []);
      setTotal(resp?.total || 0);
    } catch (e: any) {
      const msg = e?.message || 'Ошибка загрузки инцидентов';
      message.error(msg);
    } finally {
      setLoading(false);
    }
  }, [form, page, pageSize, sortBy, sortDir]);

  useEffect(() => { fetchMetrics(); }, [fetchMetrics]);
  useEffect(() => { fetchData(); }, [fetchData]);

  const onTableChange = (
    pagination: TablePaginationConfig,
    _filters: Record<string, FilterValue | null>,
    sorter: SorterResult<Incident> | SorterResult<Incident>[],
  ) => {
    setPage(pagination.current || 1);
    setPageSize(pagination.pageSize || DEFAULT_PAGE_SIZE);
    const s = Array.isArray(sorter) ? sorter[0] : sorter;
    if (s && s.field) {
      setSortBy(String(s.field));
      setSortDir(s.order === 'ascend' ? 'asc' : 'desc');
    }
  };

  const columns: ColumnsType<Incident> = useMemo(() => ([
    {
      title: 'ID',
      dataIndex: 'id',
      key: 'id',
      width: 110,
      render: (id: any) => <Button type="link" onClick={() => nav(`/incidents/${id}`)}>{id}</Button>,
    },
    {
      title: 'Заголовок',
      dataIndex: 'title',
      key: 'title',
      ellipsis: true,
    },
    {
      title: 'Статус',
      dataIndex: 'status',
      key: 'status',
      width: 120,
      render: (v: any) => statusTag(v),
      sorter: true,
    },
    {
      title: 'Severity',
      dataIndex: 'severity',
      key: 'severity',
      width: 110,
      render: (v: any) => severityTag(v),
      sorter: true,
    },
    {
      title: 'Source',
      dataIndex: 'source',
      key: 'source',
      width: 140,
      sorter: true,
    },
    {
      title: 'Trace',
      dataIndex: 'trace_id',
      key: 'trace_id',
      width: 220,
      ellipsis: true,
    },
    {
      title: 'Detected',
      dataIndex: 'detected_at',
      key: 'detected_at',
      width: 180,
      sorter: true,
      render: (v: any) => v ? dayjs(v).format('YYYY-MM-DD HH:mm:ss') : '-',
    },
    {
      title: 'Updated',
      dataIndex: 'updated_at',
      key: 'updated_at',
      width: 180,
      sorter: true,
      render: (v: any) => v ? dayjs(v).format('YYYY-MM-DD HH:mm:ss') : '-',
    },
  ]), [nav]);

  const onReset = () => {
    form.resetFields();
    setPage(1);
    setSortBy('detected_at');
    setSortDir('desc');
  };

  const statusCounters = metrics?.status_counters || {};
  const severityCounters = metrics?.severity_counters || {};

  return (
    <Space direction="vertical" size={16} style={{ width: '100%' }}>
      <Typography.Title level={3} style={{ margin: 0 }}>Инциденты</Typography.Title>

      <Card>
        <Form form={form} layout="inline" onFinish={() => { setPage(1); fetchData(); }} style={{ rowGap: 12 }}>
          <Form.Item name="status" label="Статус">
            <Select allowClear style={{ width: 160 }} options={[
              { value: 'open', label: 'open' },
              { value: 'in_progress', label: 'in_progress' },
              { value: 'resolved', label: 'resolved' },
              { value: 'closed', label: 'closed' },
            ]} />
          </Form.Item>
          <Form.Item name="severity" label="Severity">
            <Select allowClear style={{ width: 140 }} options={[1,2,3,4,5].map(v => ({ value: v, label: `SEV${v}` }))} />
          </Form.Item>
          <Form.Item name="severity_lte" label="Severity ≤">
            <Select allowClear style={{ width: 140 }} options={[1,2,3,4,5].map(v => ({ value: v, label: `SEV${v}` }))} />
          </Form.Item>
          <Form.Item name="source" label="Source">
            <Input allowClear placeholder="source" style={{ width: 160 }} />
          </Form.Item>
          <Form.Item name="date_range" label="Дата">
            <RangePicker showTime style={{ width: 340 }} />
          </Form.Item>
          <Form.Item name="trace_id" label="Trace">
            <Input allowClear placeholder="trace id" style={{ width: 220 }} />
          </Form.Item>
          <Form.Item>
            <Space>
              <Button type="primary" htmlType="submit">Применить</Button>
              <Button onClick={onReset}>Сброс</Button>
            </Space>
          </Form.Item>
        </Form>
      </Card>

      <Card loading={metricsLoading}>
        <Row gutter={16}>
          {Object.keys(statusCounters).map(k => (
            <Col key={`status-${k}`} xs={12} sm={8} md={6} lg={4} xl={3}>
              <Statistic title={`Status: ${k}`} value={statusCounters[k]} />
            </Col>
          ))}
          {Object.keys(severityCounters).map(k => (
            <Col key={`sev-${k}`} xs={12} sm={8} md={6} lg={4} xl={3}>
              <Statistic title={`SEV${k}`} value={severityCounters[k]} />
            </Col>
          ))}
        </Row>
      </Card>

      <Card>
        <Table<Incident>
          rowKey={(r) => String(r.id)}
          loading={loading}
          dataSource={data}
          columns={columns}
          pagination={{ current: page, pageSize, total, showSizeChanger: true }}
          onChange={onTableChange}
          size="middle"
        />
      </Card>
    </Space>
  );
};

export default IncidentsList;


